  });
  assert.ifError(result.error);
  return result;
}
function success(directory, command, expected, token) {
  const result = run(directory, command, token);
  assert.equal(result.status, 0, result.stderr);
  assert.deepEqual(JSON.parse(result.stdout), { savePolicy: expected });
  count++;
}
function failure(directory, command, token) {
  const result = run(directory, command, token);
  assert.equal(result.status, 1, result.stdout);
  assert.equal(result.stdout, '');
